def vt(v):
    return tuple(int(p) for p in v.split("."))

missing = []
outdated = []
for line in required.split():
    name, version = line.split("==")
    if name not in installed:
        missing.append(name)
    elif vt(installed[name]) < vt(version):
        outdated.append(name)
